namespace RisingLands;
public static class TradeOpeningV90Tests {
 static int checks;
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("FAIL v90: "+label);Console.WriteLine("PASS v90: "+label);}
 static void Report(Simulation s){Console.WriteLine($"STATE tick={s.Tick} food={s.World.Resources[1]} stone={s.World.Resources[5]} buildings="+string.Join(",",s.World.Buildings.Where(b=>b.Owner==1).Select(b=>$"{b.Type}:{s.Residents(b.Slot)}"))+" sites="+string.Join(",",s.Constructions.Where(c=>c.Owner==1).Select(c=>$"{c.Type}:{c.Progress}/{s.Rule(c.Type).Duration}"))+" troops="+string.Join(",",s.World.Units.Where(a=>a.Owner==1&&a.Health>0).GroupBy(a=>a.Type).Select(g=>$"{g.Key}:{g.Count()}")));}
 public static void Run(string root){
  var s=OpponentV75Tests.Load(root);var initial=s.World.Buildings.Single(b=>b.Owner==1&&b.Type==3);Console.WriteLine("MINES "+string.Join(";",s.World.Mines.OrderBy(m=>Math.Abs((m.Cell&255)-(initial.Cell&255))+Math.Abs((m.Cell>>8)-(initial.Cell>>8))).Take(6).Select(m=>$"{m.Cell&255},{m.Cell>>8}:{m.Quantity}:pass={s.Passable(m.Cell&255,m.Cell>>8)}")));
  Check(s.World.Buildings.Where(b=>b.Owner==1).Select(b=>b.Type).Order().SequenceEqual(new[]{2,3,4})&&s.World.Buildings.Where(b=>b.Owner==1).All(b=>s.Residents(b.Slot)==(b.Type==2?3:1)),"sanctuary starts with three colonists; crop and warehouse with one each");Check(s.World.Units.Count(a=>a.Owner==1&&a.Health>0&&a.Type==9)==7&&s.World.Units.Count(a=>a.Owner==1&&a.Type==9&&VisualCatalog.Visible(a))==2,"five internal colonists and two free colonists");Check(s.World.Units.Count(a=>a.Owner==1&&a.Health>0)==10&&s.World.Units.Count(a=>a.Owner==1&&a.Health>0&&a.Type==5)==2&&s.World.Units.Count(a=>a.Owner==1&&a.Health>0&&a.Type==7)==1&&s.World.Resources[1]==15&&s.World.Resources[5]==15&&s.World.Resources[9]==0,"workers and reduced stocks preserved without soldiers");
  var copy=OpponentV75Tests.Load(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"three-building opening saves and reloads");
  for(int i=0;i<360000&&!s.Recruitments.Any(j=>j.Owner==1&&Simulation.AdvancedAttacks.Rules.Any(r=>r.Type==j.Type)&&j.Finished);i++){s.Step();if(s.Tick%9000==0){Report(s);foreach(var a in s.World.Units.Where(a=>a.Owner==1&&a.Type is 5 or 7))Console.WriteLine($"WORKER id={a.Slot} type={a.Type} hp={a.Health} hunger={a.Satiety} at={a.X/1024},{a.Y/1024} route={a.Route.Count} foodJob={a.FoodJob} mineJob={a.MineJob} cargo={a.Food}/{a.Rock} meal="+System.Text.Json.JsonSerializer.Serialize(s.Hunger.Trips.FirstOrDefault(t=>t.Slot==a.Slot)));}}
  Report(s);var debugBuilder=s.World.Units.First(a=>a.Owner==1&&a.Type==7);Console.WriteLine("HOME PLACEMENT "+string.Join(";",NativeOpponentPlans.For(s.World)!.Plans.Where(p=>p.Allows(2)).Select(p=>$"{p.Cell&255},{p.Cell>>8}:{s.PlacementError(debugBuilder,2,p.Cell)}")));var sequence=s.Constructions.Where(c=>c.Owner==1).Select(c=>c.Type).ToArray();
  Check(sequence.Length>=2&&sequence[0]==16&&sequence[1]==8,"market first, troop exchange second");
  Check(s.World.Buildings.Any(b=>b.Owner==1&&b.Type==16&&s.Inhabited(b))&&s.World.Buildings.Any(b=>b.Owner==1&&b.Type==8&&s.Inhabited(b)),"market and exchange staffed with real colonists");
  Check(s.World.Buildings.Any(b=>b.Owner==1&&b.Type==4&&s.Inhabited(b))&&s.Cultures.Any(c=>c.Born>0&&s.World.Buildings.Any(b=>b.Slot==c.Building&&b.Owner==1)),"cultivation creates actual new colonists");
  Check(s.World.Buildings.Any(b=>b.Owner==1&&b.Type==2)&&s.World.Buildings.Any(b=>b.Owner==1&&b.Type==1),"continues with sanctuary and barracks");
  Check(s.Recruitments.Any(j=>j.Owner==1&&Simulation.AdvancedAttacks.Rules.Any(r=>r.Type==j.Type)&&j.Finished),"enemy produces troops using real resources");
  copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"grown economic population and construction ledgers load");
  for(int i=0;i<120000&&!s.Opponent.Sorties.Any(p=>s.World.Units.Any(a=>a.Slot==p.Key&&a.Owner==1));i++)s.Step();Report(s);Check(s.Opponent.Sorties.Any(p=>s.World.Units.Any(a=>a.Slot==p.Key&&a.Owner==1)),"non-allied clan develops a defended attack group after opening");
  s.Campaign.Alliances[1]=true;for(int i=0;i<300;i++)s.Step();Check(s.World.Units.Where(a=>a.Owner==1&&a.Health>0).All(a=>a.AttackTarget<0)&&!s.Opponent.Sieges.Any(p=>s.World.Units.Any(a=>a.Slot==p.Key&&a.Owner==1)),"alliance suppresses attacks");
  s.Restart();Check(s.Tick==0&&s.World.Buildings.Single(b=>b.Owner==1&&b.Type==3).Type==3&&s.World.Resources[1]==15,"restart retains new opening");Console.WriteLine("ALL v90 TRADE OPENING TESTS PASSED: "+checks);
 }
}
